The two Python functions below sort a list in ascending order and return the number of swaps they perform.

```python
def bubble_swaps(a):
    n, swaps = len(a), 0
    for i in range(n - 1):
        for j in range(n - 1 - i):
            if a[j] > a[j + 1]:
                a[j], a[j + 1] = a[j + 1], a[j]
                swaps += 1
    return swaps

def selection_swaps(a):
    n, swaps = len(a), 0
    for i in range(n - 1):
        m = i
        for j in range(i + 1, n):
            if a[j] < a[m]:
                m = j
        if m != i:
            a[i], a[m] = a[m], a[i]
            swaps += 1
    return swaps

B = bubble_swaps([6, 2, 9, 4, 1, 7])
S = selection_swaps([6, 2, 9, 4, 1, 7])
